head.script:
scwin.fun_import = function(a, b) {
    return a.label + " (" + a.value + ")";
}
scwin.fun_display = function(data) {
    var arrTemp = data.split("(");
    return arrTemp[1].replace(")", "");
}
scwin.fun_display = function(data) {
    var arrTemp = data.split("(");
    return arrTemp[1].replace(")", "") + "_scopeFormatter";
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#autoComplete1_label').text() == 'a1_scopeFormatter'", "true");
    WebSquare.wUnit.addCommand('pause', '500');
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    dataList1.setJSON([{
        "label": "가나다",
        "value": "a1"
    }, {
        "label": "고노도",
        "value": "a2"
    }, {
        "label": "하카타",
        "value": "a3"
    }]);
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
